<script setup lang="ts">import { X } from '@lucide/vue'; import UiCheckbox from '../../../components/ui/UiCheckbox.vue'; import UiInput from '../../../components/ui/UiInput.vue'; import UiSelect from '../../../components/ui/UiSelect.vue'; import UiTextarea from '../../../components/ui/UiTextarea.vue'; import UiButton from '../../../components/ui/UiButton.vue'; import UiDialog from '../../../components/ui/UiDialog.vue'; import { COUNTRY_OPTIONS } from '../../../constants/countries'; import type { BrandPayload } from '../types/brand.types'; import { slugPattern } from '../../catalog/validation/slug'; defineProps<{ open:boolean; title:string; busy:boolean; error:string; form:BrandPayload }>(); const emit=defineEmits<{close:[];submit:[];updateName:[string];updateSlug:[string]}>()</script>
<template><UiDialog :open="open" labelledby="brand-dialog-title" :close-disabled="busy" panel-class="w-full max-w-2xl" @close="emit('close')"><form class="max-h-[90vh] w-full overflow-y-auto rounded-xl bg-white p-6 shadow-xl" @submit.prevent="emit('submit')"><div class="flex items-start justify-between"><h2 id="brand-dialog-title" class="text-lg font-bold">{{title}}</h2><UiButton type="button" variant="ghost" size="sm" aria-label="Закрыть окно бренда" :disabled="busy" @click="emit('close')"><X :size="20"/></UiButton></div><p v-if="error" role="alert" class="mt-3 text-sm text-error-500">{{error}}</p><div class="mt-6 grid gap-4 sm:grid-cols-2"><label>Название<UiInput :model-value="form.name" required data-autofocus @update:model-value="emit('updateName',$event)"/></label><label>Slug<UiInput :model-value="form.slug" required :pattern="slugPattern" @update:model-value="emit('updateSlug',$event)"/></label><label>Страна<UiSelect :model-value="form.country_code ?? ''" :options="COUNTRY_OPTIONS" accessible-name="Страна происхождения" searchable @update:model-value="form.country_code=$event||null"/></label><label class="sm:col-span-2">Описание<UiTextarea v-model="form.description"/></label><UiCheckbox class="sm:col-span-2" mode="boolean" :checked="form.is_active" @update:checked="form.is_active=$event">Бренд активен</UiCheckbox></div><div class="mt-6 flex justify-end gap-3"><UiButton type="button" variant="secondary" :disabled="busy" @click="emit('close')">Отмена</UiButton><UiButton :loading="busy">Сохранить</UiButton></div></form></UiDialog></template>
